import fs from 'node:fs';
const p='index.html';
let s=fs.readFileSync(p,'utf8');
const marker='/* MOMOIROBARA TARGETED REPAIR V6 */';
if(s.includes(marker)) process.exit(0);
s=s.replace(/<script[^>]*id="momo-targeted-repair-v6"[^>]*>[\s\S]*?<\/script>/gi,'');
const css=`${marker}
button:active,.tool:active,.pl-item:active,.song:active,.nav button:active,.side-action:active{transform:scale(.96)!important;transition:transform .08s ease!important}.momo-ripple{position:fixed;z-index:99999;width:7px;height:7px;border-radius:50%;pointer-events:none;background:var(--a);animation:momoRipple .42s ease-out forwards}@keyframes momoRipple{0%{opacity:.75;transform:translate(-50%,-50%) scale(.5)}100%{opacity:0;transform:translate(-50%,-50%) scale(8)}}
#mobileMenuClose{display:none!important;position:fixed!important;z-index:10001;width:34px;height:34px;place-items:center;border:1px solid var(--border);border-radius:50%;background:var(--solid);color:var(--muted)}body.momo-menu-open #mobileMenuClose{display:grid!important}.player input[type=range],.player-bar input[type=range],.progress input[type=range]{--momo-progress:0%;background:linear-gradient(90deg,var(--a),var(--b) var(--momo-progress),var(--track) var(--momo-progress),var(--track))!important;border:0!important}.player input[type=range]::-webkit-slider-runnable-track,.player-bar input[type=range]::-webkit-slider-runnable-track,.progress input[type=range]::-webkit-slider-runnable-track{height:6px;background:transparent!important}[data-density],.density-setting,.density-control,.interface-density{display:none!important}.settings-button svg,.settings-btn svg,[aria-label="Settings"] svg,[title="Settings"] svg{display:block!important;visibility:visible!important;opacity:1!important}.lyric-line,[data-lyric-line],.lyrics-line,[class*="lyric"] [data-time]{cursor:pointer}.lyric-line:hover,[data-lyric-line]:hover,.lyrics-line:hover,[class*="lyric"] [data-time]:hover{color:var(--a)!important;transform:translateX(3px)}`;
s=s.replace(/<\/style>/i,css+'</style>');
const js=`<script id="momo-targeted-repair-v6">(()=>{const A=(x,r=document)=>[...r.querySelectorAll(x)],N=v=>{const n=parseFloat(v);return Number.isFinite(n)?n:null};const density=()=>A('[data-density],.density-setting,.density-control,.interface-density').forEach(e=>(e.closest('.setting,.setting-row,.setting-item,.control-row')||e).remove());const progress=()=>A('input[type="range"]').forEach(r=>{const m=N(r.max),v=N(r.value);if(m)r.style.setProperty('--momo-progress',Math.max(0,Math.min(100,v/m*100))+'%')});const menu=()=>{const x=document.querySelector('.side');document.body.classList.toggle('momo-menu-open',!!x&&(x.classList.contains('open')||x.classList.contains('show')||x.classList.contains('active')))};const close=()=>{let b=document.getElementById('mobileMenuClose');if(!b){b=document.createElement('button');b.type='button';b.id='mobileMenuClose';b.setAttribute('aria-label','Close menu');b.innerHTML='<svg viewBox="0 0 24 24"><path d="M7 7l10 10M17 7 7 17"/></svg>';document.body.appendChild(b)}b.onclick=()=>{document.querySelector('.side')?.classList.remove('open','show','active');menu()};const x=document.querySelector('.side');if(x)new MutationObserver(menu).observe(x,{attributes:true,attributeFilter:['class']});menu()};const ripple=()=>document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('button,.tool,.pl-item,.song,.nav button,.side-action'))return;const r=document.createElement('span');r.className='momo-ripple';r.style.left=e.clientX+'px';r.style.top=e.clientY+'px';document.body.appendChild(r);r.onanimationend=()=>r.remove()},{passive:true});const lyrics=()=>document.addEventListener('click',e=>{const l=e.target.closest?.('.lyric-line,[data-lyric-line],.lyrics-line,[class*="lyric"] [data-time]');if(!l)return;const a=document.querySelector('audio');let t=null;for(const k of ['data-time','data-start','data-timestamp','data-seconds']){const v=N(l.getAttribute?.(k));if(v!==null){t=v;break}}if(t===null){const m=(l.textContent||'').match(/(?:^|\s)(\d{1,2}):(\d{2})(?:\s|$)/);if(m)t=+m[1]*60+ +m[2]}if(a&&t!==null)a.currentTime=Math.max(0,t)},true);const init=()=>{density();progress();close();ripple();lyrics();document.addEventListener('input',progress,true);document.addEventListener('change',progress,true)};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init()})()</script>`;s=s.replace(/<\/body>/i,js+'</body>');fs.writeFileSync(p,s);console.log('V6 repair applied');